import { protect, restrictTo } from "@/middleware/auth.middleware";
import { validate, validateParams } from "@/middleware/validation.middleware";
import { Router } from "express";
import { approveRentRequest, cancelRentRequest, createRentRequest, downloadLeaseAgreement, getAllRentRequests, getLandlordRentRequests, getMyRentRequests, getRentRequestById, refundEscrow, rejectRentRequest, releaseEscrow, updateRentRequest, } from "./rentrequest.controller";
import { createRentRequestSchema, decideRentRequestSchema, rentRequestParamsSchema, updateRentRequestSchema, } from "./rentrequest.validation";
const router = Router();
router.use(protect);
router.post("/", restrictTo("TENANT"), validate(createRentRequestSchema), createRentRequest);
router.get("/tenant", restrictTo("TENANT"), getMyRentRequests);
router.get("/landlord", restrictTo("LANDLORD"), getLandlordRentRequests);
router.get("/", restrictTo("ADMIN"), getAllRentRequests);
router.get("/:id/lease-agreement", restrictTo("TENANT", "LANDLORD", "ADMIN"), validateParams(rentRequestParamsSchema), downloadLeaseAgreement);
router.get("/:id", restrictTo("TENANT", "LANDLORD", "ADMIN"), validateParams(rentRequestParamsSchema), getRentRequestById);
router.patch("/:id", restrictTo("TENANT"), validateParams(rentRequestParamsSchema), validate(updateRentRequestSchema), updateRentRequest);
router.patch("/:id/cancel", restrictTo("TENANT"), validateParams(rentRequestParamsSchema), cancelRentRequest);
router.patch("/:id/approve", restrictTo("LANDLORD"), validateParams(rentRequestParamsSchema), validate(decideRentRequestSchema), approveRentRequest);
router.patch("/:id/reject", restrictTo("LANDLORD"), validateParams(rentRequestParamsSchema), validate(decideRentRequestSchema), rejectRentRequest);
router.patch("/escrow/:id/release", restrictTo("LANDLORD", "ADMIN"), validateParams(rentRequestParamsSchema), releaseEscrow);
router.patch("/escrow/:id/refund", restrictTo("ADMIN"), validateParams(rentRequestParamsSchema), refundEscrow);
export { router as rentRequestRouter };
